  ],
  "license": "MIT",
  "engines": {
    "node": ">=18"
  }
}
EOF
cat > lib/index.js <<'EOF'
'use strict'

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Uses the native `Object.setPrototypeOf` when available, falls back to the
 * `__proto__` accessor, and as a last resort copies the prototype's own
 * properties onto the object (for environments with neither).
 */
module.exports = Object.setPrototypeOf ||
  ({ __proto__: [] } instanceof Array ? setProtoOf : mixinProperties)

function setProtoOf (obj, proto) {
  obj.__proto__ = proto
  return obj
}

function mixinProperties (obj, proto) {
  for (const prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop]
    }
  }
  return obj
}

module.exports.setProtoOf = setProtoOf
module.exports.mixinProperties = mixinProperties
EOF
cat > lib/index.d.ts <<'EOF'
declare function setPrototypeOf<T extends object>(obj: T, proto: object | null): T

declare namespace setPrototypeOf {
  function setProtoOf<T extends object>(obj: T, proto: object | null): T
  function mixinProperties<T extends object>(obj: T, proto: object | null): T
}

export = setPrototypeOf
EOF
cat > test/index.test.js <<'EOF'
'use strict'

const { test } = require('node:test')
const assert = require('node:assert/strict')
const setPrototypeOf = require('..')

const proto = { greet () { return 'hi' } }

test('sets the prototype and returns the object', () => {
  const obj = {}
  assert.equal(setPrototypeOf(obj, proto), obj)
  assert.equal(Object.getPrototypeOf(obj), proto)
  assert.equal(obj.greet(), 'hi')
})

test('accepts a null prototype', () => {
  const obj = setPrototypeOf({}, null)
  assert.equal(Object.getPrototypeOf(obj), null)
})

test('__proto__ fallback sets the prototype', () => {
  const obj = setPrototypeOf.setProtoOf({}, proto)
  assert.equal(Object.getPrototypeOf(obj), proto)
})

test('mixin fallback copies properties without overwriting own ones', () => {
  const obj = setPrototypeOf.mixinProperties({ greet: 'own' }, { greet: 'x', other: 1 })
  assert.equal(obj.greet, 'own')
  assert.equal(obj.other, 1)
})
EOF
cat > .gitignore <<'EOF'
node_modules/
